const raiz = document.getElementById('raiz');
const incrustado = document.getElementById('datos');

if (incrustado) {
  // SSR y SSG: el HTML ya trae la pantalla y los datos; React se «engancha» a lo que existe.
  const { pedidos, generado } = JSON.parse(incrustado.textContent);
  hydrateRoot(raiz, <App pedidos={pedidos} generado={generado} />);
} else {
  // CSR: el HTML vino vacío; hay que pedir los datos y recién ahí dibujar.
  fetch('/api/pedidos').then((r) => r.json()).then(({ pedidos, generado }) => {
    createRoot(raiz).render(<App pedidos={pedidos} generado={generado} />);
  });
}

// SSR: se arma en cada pedido
if (ruta === '/ssr') return enviar(paginaConDatos(await getPedidos()));

// SSG: se armó antes (generar-ssg.js), el servidor solo lee un archivo
if (ruta === '/ssg') return enviar(fs.readFileSync('dist/ssg.html'));

// ISR: servir lo guardado; si venció, servirlo igual y regenerar en segundo plano
if (ruta === '/isr') {
  if (!isr) { await regenerar(); return enviar(isr.html); }
  const viejo = Date.now() - isr.t > REVALIDAR_MS;
  if (viejo && !isrRegenerando) void regenerar();
  return enviar(isr.html);
}
